	private static int availableTaskSlots() {
		int maximum = LmdbNativeParallelPipelines.configuredMaxTasks();
		LmdbNativeParallelPipelines.TaskReservation quote = LmdbNativeParallelPipelines.quoteTasks(false, maximum);
		if (quote == null) {
			return 0;
		}
		try (quote) {
			return quote.grantedWorkers();
		}
	}

	private static NativeSlotLayout layout() {
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		names.put("v0", 0);
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(new ArrayList<>(names.keySet()));
		return layout;
	}

	private static int availableHedgePermits() {
		for (int threshold = 1; threshold < 4_096; threshold++) {
			LmdbNativeHedgeConfig config = hedgeConfig(threshold);
			if (!LmdbNativeHedgePermits.spareCapacity(config)) {
				return threshold / 2;
			}
		}
		throw new AssertionError("the available hedge permit count exceeded the diagnostic bound");
	}

	private static LmdbNativeHedgeConfig hedgeConfig(int maxConcurrentHedges) {
		return new LmdbNativeHedgeConfig(true, true, 200_000L, 0.25, 0.5, 0.5, maxConcurrentHedges, 1, 4.0, 4,
				1_024, 10_000_000L, 1.25, 8.0, 0.75, 0.95, 5);
	}

	private static void throwUnchecked(Throwable failure) {
		if (failure instanceof RuntimeException runtime) {
			throw runtime;
		}
		if (failure instanceof Error error) {
			throw error;
		}
		throw new AssertionError("expected an unchecked setup failure", failure);
	}
